def learning_type(has_labels, has_reward, some_labels):
    if has_reward:
        return "reinforcement"
    if has_labels and not some_labels:
        return "supervised"
    if has_labels and some_labels:
        return "semi-supervised"
    return "unsupervised"

print(learning_type(has_labels=False, has_reward=False, some_labels=False))

def learning_type(has_labels, has_reward, some_labels):
    if has_labels and not some_labels:
        return "supervised"
    if has_reward:
        return "reinforcement"
    if has_labels and some_labels:
        return "semi-supervised"
    return "unsupervised"
